import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import React, { Component } from "react";
import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import { changePage } from "../../actions/pageActions";
import {
  Checkbox,
  Snackbar,
  Paper,
  Tab,
  Tabs,
  Box,
  MenuItem,
  Breadcrumbs,
  Link,
  Select,
  Button,
  FormHelperText,
  FormControl,
  InputLabel
} from "@material-ui/core";
import { makeStyles } from "@material-ui/core/styles";

class ProcessGroupDetail extends Component {
  state = {
    value: 0
  };
  onPageChangeClick = (navType, page, objId) => {
    const pageDetail = {
      navType,
      page,
      objId
    };
    this.props.changePage(pageDetail);
  };
  handleChange = (event, newValue) => {
    this.setState({ value: newValue });
  };

  render() {
    function renderPageSwitch(index) {
      switch (index) {
        case 0:
          return "Shows all items and their respoective unpacking processes/ if it has been configured";
        case 1:
          return "Add vendor items here";
        case 2:
          return "pull reports base on items, and any details below";
        case 3:
          return "signed service agreement with the current state of config.  IF there is changed configs, those changes will show up here and will indicate to reduline the contract with those new items.  Also feature of auto generate the contract will be included";
        case 4:
          return "Shows all items to be billed for over here. configure the payments period over here. checks printing and mailing api will be linked to this ";
        case 5:
          return "shows a log of all items that do not pass vailidation along with other client complaints";
        case 6:
          return "if this vendor is a client, shows payments and billing, along with a unified net payments/billing description";

        default:
          return "Undefined Tab Index";
      }
    }
    return (
      <Grid container>
        <Grid item sm sm={12}>
          <Paper style={{ padding: 20, margin: 10 }}>
            <Breadcrumbs
              style={{
                display: "flex",
                justifyContent: "center"
              }}
            >
              <Link
                onClick={this.onPageChangeClick.bind(
                  this,
                  "MainNav",
                  "ProcessGroups",
                  0
                )}
                href="#"
              >
                Process Groups
              </Link>

              <Typography color="textPrimary">Process Group Details</Typography>
            </Breadcrumbs>
          </Paper>
          <Paper style={{ padding: 10, margin: 10 }}>
            <h4>Process Group Name: Ball Nut Production</h4>
            <p>Process Group ID:{this.props.id}</p>

            <div
              style={{
                display: "flex",
                justifyContent: "center"
              }}
            >
              <div title="Please select processes to add to the below process group.  This will add the process to this group for organization purposes.  Each process utilizes item(s) and generates item(s)">
                <InfoIcon />{" "}
                <FormControl style={{ minWidth: 200 }}>
                  <InputLabel id="demo-simple-select-helper-label">
                    Choose Process
                  </InputLabel>
                  <Select labelId="demo-simple-select-helper-label">
                    <MenuItem value={1}>Machining</MenuItem>
                    <MenuItem value={2}>Assembly</MenuItem>
                    <MenuItem value={3}>CMM Validation</MenuItem>
                    <MenuItem value={4}>Visual Validation</MenuItem>
                  </Select>
                </FormControl>{" "}
                <Button>
                  <AddIcon />
                </Button>
              </div>
            </div>
          </Paper>
        </Grid>
        <Grid item sm={2}>
          <Paper style={{ padding: 20, margin: 10 }}>
            <Tabs
              orientation="vertical"
              variant="scrollable"
              value={this.state.value}
              onChange={this.handleChange}
            >
              <Tab label="Items" value={1} />
              <Tab label="Unpacking Processes" value={0} />
              <Tab label="Reports" value={2} />
              <Tab label="Service Agreement" value={3} />
              <Tab label="Payments" value={4} />
              <Tab label="Identified Issues" value={5} />
              <Tab label="Vendor as Client" value={6} />
            </Tabs>
          </Paper>
        </Grid>
        <Grid item sm sm={10}>
          <Paper style={{ padding: 20, margin: 10 }}>
            {renderPageSwitch(this.state.value)}
          </Paper>
        </Grid>
      </Grid>
    );
  }
}

const mapStateToProps = state => ({
  auth: state.auth
});

export default connect(mapStateToProps, { changePage })(ProcessGroupDetail);
